constraints:
1 ≤ N ≤ 10^{6}
0 ≤ Arr[i] ≤ 10^{9}

expected time complexity: O(N)
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def maxIndexDiff(self, arr, n):
		m = -100000
		for i in range(n):
			j = n - 1
			while i < j and arr[i] > arr[j]:
				j -= 1
			m = max(m, j - i)
		return m
